package in.smkt.haldesk;
import java.net.URL;import org.junit.Test;import static org.junit.Assert.*;
public class FinbertPolicyJUnitTest{
 @Test public void modelIsPinnedAndChecksummed(){assertFalse(FinbertClassifier.MODEL_URL.contains("/main/"));assertTrue(FinbertClassifier.MODEL_URL.contains(FinbertClassifier.REVISION));assertTrue(FinbertClassifier.MODEL_SHA256.matches("[a-f0-9]{64}"));assertTrue(FinbertClassifier.VOCAB_SHA256.matches("[a-f0-9]{64}"));assertEquals(110717965L,FinbertClassifier.MODEL_BYTES);}
 @Test public void downloadAllowlistRejectsCredentialAndNonHttpsUrls()throws Exception{assertTrue(FinbertClassifier.allowedDownload(new URL("https://huggingface.co/model")));for(String u:new String[]{"http://huggingface.co/model","https://huggingface.co.evil.example/model","https://user:password@huggingface.co/model","https://huggingface.co:8443/model","https://example.org/model"})assertFalse(FinbertClassifier.allowedDownload(new URL(u)));}
 @Test public void unsupportedLanguagesAreNotInvented(){assertTrue(FinbertClassifier.supportedLanguage("HAL announces earnings","en"));assertFalse(FinbertClassifier.supportedLanguage("HAL announces earnings","fr"));assertFalse(FinbertClassifier.supportedLanguage("हिन्दुस्तान एयरोनॉटिक्स","en"));assertFalse(FinbertClassifier.supportedLanguage("123","en"));}
 @Test public void cancelledQueuedDownloadCannotRestart()throws Exception{java.nio.file.Path dir=java.nio.file.Files.createTempDirectory("finbert-cancel");try{FinbertClassifier f=new FinbertClassifier(dir.toFile());long ticket=f.newOperation();f.cancel();try{f.install(p->{throw new AssertionError("No progress after cancellation");},ticket);fail("cancelled task ran");}catch(java.io.IOException e){assertTrue(e.getMessage().contains("cancelled"));}assertFalse(new java.io.File(dir.toFile(),"offline-finbert").exists());assertFalse(f.isInstalling());}finally{java.nio.file.Files.delete(dir);}}
 @Test public void cancelledQueuedInferenceFailsBeforeLoadingModel()throws Exception{FinbertClassifier f=new FinbertClassifier(new java.io.File("missing-synthetic-model"));long ticket=f.newOperation();f.cancel();try{f.score(new org.json.JSONArray(),ticket);fail("cancelled inference ran");}catch(java.io.IOException e){assertTrue(e.getMessage().contains("cancelled"));}}
 @Test public void newUserOperationDoesNotReviveAnOlderTicket()throws Exception{FinbertClassifier f=new FinbertClassifier(new java.io.File("missing-synthetic-model"));long old=f.newOperation(),current=f.newOperation();assertTrue(current>old);try{f.score(new org.json.JSONArray(),old);fail("superseded task ran");}catch(java.io.IOException e){assertTrue(e.getMessage().contains("cancelled"));}try{f.score(new org.json.JSONArray(),current);fail("missing model accepted");}catch(java.io.IOException e){assertTrue(e.getMessage().contains("Download the offline model"));}}
}
